{
  "name": "mm_dhcp_packet_notify",
  "confidence": "medium",
  "docstring": "Processes a DHCP/ARP-offload packet indicator, stores packet fields in the station context, clears any pending critical state, and dispatches kernel event 98.",
  "subsystem": "mm",
  "var_renames": {
    "v4": "station_array_base",
    "v6": "station_index",
    "v10": "station_context",
    "v11": "packet_status_byte",
    "v12": "critical_pending_flag",
    "v13": "packet_word"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "32-bit packet identifier or buffer pointer copied into station context"
    },
    {
      "offset": 4,
      "meaning": "packet status/type byte copied into station context"
    },
    {
      "offset": 5,
      "meaning": "station/VIF index byte"
    },
    {
      "offset": 94,
      "meaning": "byte flag tested for ARP offload/DHCP station condition"
    },
    {
      "offset": 121,
      "meaning": "byte indicating a pending critical section for this station context"
    },
    {
      "offset": 124,
      "meaning": "critical-section lock or handle passed to ke_exit_critical"
    },
    {
      "offset": 140,
      "meaning": "station context byte mirroring packet status/type byte"
    },
    {
      "offset": 144,
      "meaning": "station context dword mirroring packet identifier or buffer pointer"
    }
  ]
}
